<!-- subpkg-patient/consultation/detail.vue -- 接收?id=参数，调medicalAPI.getReportDetail(id)，对齐Web ConsultationDetail -->
<template><view class="p"><NavBar title="会诊详情" :showBack="true"/><LoadingSkeleton v-if="ld"/><view v-else-if="c" class="bd"><view class="h"><text class="sk">医生会诊详情</text><text class="hi">会诊 #{{c.id}}</text></view><image v-if="iu" :src="iu" mode="aspectFit" class="im"/><view class="cd"><text class="ct">医生诊断意见</text><text class="dg">{{c.doctorDiagnosis||'暂未提交诊断'}}</text></view><view class="cd"><text class="ct">沟通记录 ({{mg.length}}条)</text><view v-if="!mg.length" style="color:rgba(200,218,242,0.5);font-size:24rpx;padding:40rpx 0;text-align:center">暂无</view><view v-for="m in mg" :key="m.id" class="msg" :class="m.senderRole==='DOCTOR'?'md':'mp'"><text class="mm">{{m.senderRole==='DOCTOR'?'医生':(c.patientName||'患者')}} · {{m.createdAt}}</text><text class="mtx">{{m.content}}</text></view></view></view></view></template>
<script setup>import{ref,computed,onMounted}from'vue';import NavBar from'@/components/nav-bar.vue';import LoadingSkeleton from'@/components/loading-skeleton.vue';import{medicalAPI}from'@/api/medical';import{ensureImageUrl}from'@/utils/image'
const ld=ref(true);const c=ref(null);const mg=ref([])
const iu=computed(()=>c.value?ensureImageUrl(c.value.imageUrl):null)
onMounted(async()=>{const id=getCurrentPages().pop()?.options?.id;if(!id)return;try{const r=await medicalAPI.getReportDetail(id);c.value=r?.data||r;mg.value=r?.messages||[]}catch(e){}finally{ld.value=false}})</script>
<style scoped>.p{min-height:100vh;background:#040b16}.bd{padding:28rpx}.h{display:flex;flex-direction:column;gap:14rpx;margin-bottom:28rpx}.sk{display:inline-flex;padding:6rpx 16rpx;background:rgba(34,211,238,0.08);border:1px solid rgba(34,211,238,0.18);border-radius:999rpx;color:#86e9ff;font-size:22rpx;width:fit-content;font-weight:600}.hi{font-size:40rpx;font-weight:800;color:#f7fbff}.im{width:100%;min-height:400rpx;border-radius:20rpx;background:rgba(6,17,30,0.9);margin-bottom:28rpx}.cd{padding:24rpx;border-radius:22rpx;background:linear-gradient(180deg,rgba(7,21,36,0.94),rgba(4,12,24,0.96));border:1px solid rgba(125,211,252,0.12);margin-bottom:20rpx}.ct{font-size:30rpx;font-weight:700;color:#f7fbff;margin-bottom:20rpx;display:block}.dg{font-size:28rpx;color:rgba(200,218,242,0.8);line-height:1.8}.msg{max-width:80%;margin-bottom:20rpx;padding:20rpx 24rpx;border-radius:16rpx}.md{margin-left:auto;background:linear-gradient(135deg,rgba(14,165,233,0.2),rgba(16,185,129,0.18));border:1px solid rgba(94,234,212,0.18)}.mp{background:rgba(8,20,35,0.7);border:1px solid rgba(125,211,252,0.08)}.mm{font-size:20rpx;color:rgba(200,218,242,0.5);display:block;margin-bottom:8rpx}.mtx{font-size:28rpx;color:#eef7ff;line-height:1.7}</style>
